            PyArray_NDIM(char_array), PyArray_DIMS(char_array), type);
    if (result == NULL) {
        goto err;
    }

    out_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)result);
    if (out_iter == NULL) {
        goto err;
    }

    if (input_type == NPY_UNICODE) {
        npy_intp nchars = itemsize / 4;
        while (PyArray_ITER_NOTDONE(in_iter)) {
            npy_bool value = NPY_TRUE;
            npy_ucs4 *data = (npy_ucs4 *)PyArray_ITER_DATA(in_iter);
            npy_intp length = nchars;

            while (length > 0 && data[length - 1] == 0) {
                length--;
            }
            if (length == 0) {
                value = NPY_FALSE;
            }
            else {
                npy_intp i;
                for (i = 0; i < length; i++) {
