            while (length > 0 && data[length - 1] == 0) {
                length--;
            }
            if (length == 0) {
                value = NPY_FALSE;
            }
            else {
                int i;
                for (i = 0; i < length; i++) {
                    unsigned char c = data[i];
                    if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z'))) {
